/* 头像插画资源（生成物）：默认聊天对象与用户本人的内联头像。
   core/kit.js 的 avatar() 只接受 data:image/(jpeg|png|webp|svg+xml);base64 内联图，故以 data URI 内嵌。
   2026-10-06 需求起键从四个收敛成两个（用户原话：「聊天对象的默认头像 太丑了，统一换成 <图>，
   并将它加入资产中」—— 林间 / 陈一 / 小满 三张旧插画不再各有一张，p1 / p2 / p3 三个键作废）：
   · chat —— **聊天对象的默认头像**（键盘形态与主 App 形态共用这一张）：**2026-10-26 需求换成用户
     提供的人形图标** —— 灰色实心圆 + 挖空的人形，原填充 #8A8A8A，以 **SVG data URI** 内嵌（矢量、
     任意尺寸都清晰；落进圆形头像槽就是一枚「灰底 + 白人形」的默认头像，透明处由 `.avatar img`
     的白底垫上）。原图入库在 assets/avatars/default.svg。凡是没设自定义头像的聊天对象都用它 ——
     默认的三个对象、新建的对象、老存档里挂着旧默认头像的那些（见下面的 retiredChatPrefix）。
     2026-10-06 ～ 10-26 用的是那张中性线稿插画（384×384 PNG 透明底，原图 assets/avatars/default.png
     保留备查、不再内嵌）。
   · self —— 「我」自己的头像（AI 生成的 320×320 JPEG），本轮不动。
  · peer —— 宿主会话（林间）对方的头像：系统内置的女生头像（选图面板头像模式候选批次
    的 mock-1「长发女生」，AI 生成 320×320 JPEG；2026-10-06 需求：聊天样式页不再用
    akalin 线稿）。由 app.js 的 HOST_CHAT 读取，kb-usage-guide 的聊天页跟着同一份。
   读取方（app.js）一律用 `|| ''` 兜底，文件缺失不影响渲染。
   retiredPrefix 是**被换掉的那批旧默认头像的识别前缀**：AI 生成的内联 JPEG 一律带
   JFIF + Exif 头（`/9j/4AAQSkZJRgABAQAASABIAAD/`），而用户自己上传 / 从候选里选的插画都经
   canvas 重压、不带 Exif（见 app.js 的 avatar-input 与 confirm-avatar）。老 localStorage 存档
   把默认头像当成「用户头像」存了下来，加载时按这个前缀识别并重指到 chat
   （见 app.js 的 retiredAvatar()）—— 否则改完头像老存档里还是旧的那三张。
   retiredChatPrefix 是 **2026-10-06 ～ 10-26 那张默认头像插画**（384×384 PNG）的识别前缀：老存档里
   默认对象把当时的 AV.chat 整串写进了 partner.avatar，换图后那些对象会一直挂着旧插画 —— 加载时按
   这个前缀认出来清空、回落到新的 chat（见 app.js 的 keepAvatar()）。只认这一张的 IHDR 头，上传 /
   候选头像都是 canvas 重压的 JPEG，不会误伤。 */
window.LOVECO_AVATARS = {
  chat: "data:image/svg+xml;base64,",
  self: "data:image/jpeg;base64,",
  peer: "data:image/jpeg;base64,"
};
/* 老默认头像的识别前缀（见上）：只用于识别「系统给的默认头像」，不参与渲染 */
window.LOVECO_AVATARS.retiredPrefix = 'data:image/jpeg;base64,/9j/4AAQSkZJRgABAQAASABIAAD/';
/* 2026-10-06 ～ 10-26 那张默认头像插画（384×384 PNG）的识别前缀，见文件头 retiredChatPrefix */
window.LOVECO_AVATARS.retiredChatPrefix = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAYAAAAGACAYAAACkx7W/';
